    #[test]
    fn test_barrier() {
        let v1 = vec![1, 2, 3];
        assert!(barrier(&v1, 0)); // [1] < [2,3]
        assert!(barrier(&v1, 1)); // [1,2] < [3]
        assert!(barrier(&v1, 2)); // last index, vacuously true

        let v2 = vec![1, 3, 2];
        assert!(barrier(&v2, 0)); // [1] < [3,2] holds since 1<2 and 1<3
        assert!(!barrier(&v2, 1)); // [1,3] < [2] fails (3<2 is false)

        let v3 = vec![5];
        assert!(barrier(&v3, 0)); // single element

        let v4 = vec![2, 1];
        assert!(!barrier(&v4, 0)); // 2<1 is false
    }
